package com.amit.jobagent.application;import jakarta.persistence.*;import java.util.UUID;
@Entity @Table(name="generated_claim_source")class GeneratedClaimSource{@Id UUID id;@Column(name="generated_claim_id",nullable=false,updatable=false)UUID claimId;@Column(name="candidate_fact_id",updatable=false)UUID factId;@Column(name="job_requirement_id",updatable=false)UUID requirementId;@Column(name="job_field_reference",updatable=false,length=100)String jobField;protected GeneratedClaimSource(){}GeneratedClaimSource(UUID claim,UUID fact,UUID requirement,String field){id=UUID.randomUUID();claimId=claim;factId=fact;requirementId=requirement;jobField=field;}}
